-- ── Esteban Carreras ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Esteban Carreras',
        'nicaragua',
        'Années 2000 — Craig Cunningham, Estelí',
        'Usine propre — Tabacalera Carreras S.A., Estelí',
        'wantedonline.co.za « Cigars from Esteban Carreras explore the best of Nicaragua » (2 janvier 2026 : origines que la presse elle-même dit mystérieuses — un rouleur cubain anonyme dans les années 1990, un nom emprunté à un passeur d''après la révolution ; depuis le début ou le milieu des années 2000, Craig Cunningham, entrepreneur américain, possède et dirige la maison et a établi la Tabacalera Carreras à Estelí ; siège en Californie ; treize lignes dont Cashmere, Dictator''s Hand, Hellcat, Chupacabra, Unforsaken, Black Cross, Brown Cross, Bloodline, Mr Brownstone ; Chupacabra 10 Años en cape San Andrés ; roule aussi pour d''autres marques ; à l''Inter-tabac 2024, distribution mondiale avec Kopp Tobaccos) ; estebancarreras.com (la majorité des cigares sont des puros nicaraguayens) ; klarocigars.com (entretien avec Cunningham à la TPE 2024 : la légende du nom, liée à une semence corojo sortie de Cuba)',
        'Esteban Carreras est un nom dont personne ne sait vraiment qui il désigne, et la presse du métier a l''honnêteté de le dire : la marque aurait été lancée dans les années 1990 par un rouleur cubain resté anonyme, et le nom viendrait d''un passeur qui aida des Cubains à fuir après la révolution — ou, selon ce que le propriétaire a raconté à un détaillant en 2024, d''une histoire de semences de corojo sorties de l''île. L''atlas rapporte ces récits à ceux qui les font et n''en retient aucun comme date de fondation.

Ce qui est établi commence au début ou au milieu des années 2000 : Craig Cunningham, entrepreneur américain, possède et dirige la maison depuis lors, et il a établi à Estelí sa propre fabrique, la Tabacalera Carreras, où tout se cultive ou s''achète, s''assemble et se roule. La maison a son siège en Californie et son marché aux États-Unis ; en 2024, à l''Inter-tabac de Dortmund, elle a annoncé sa distribution mondiale avec Kopp Tobaccos. La fabrique roule aussi pour d''autres marques, qu''elle ne nomme pas.

Le catalogue compte treize lignes — Cashmere, Dictator''s Hand, Hellcat, Chupacabra, Unforsaken, Black Cross, Brown Cross, Bloodline, Mr Brownstone — et la maison dit que la majorité sont des puros nicaraguayens. Chupacabra, en trois versions, est celle qui a fait sa réputation.',
        '[{"name":"Chupacabra","color":"#4A3728","force":"Full","wrapper":"Nicaraguayenne ; San Andrés pour la 10 Años","vitolas":[],"story":"La ligne qui a fait la réputation — Natural, Maduro et 10 Años, tête en queue de cochon."},{"name":"Cashmere","color":"#C9A96E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''une des treize lignes ; la maison dit que la majorité sont des puros nicaraguayens."}]',
        'Esteban Carreras is a name nobody quite knows the bearer of, and the trade press is honest enough to say so: the brand is said to have been started in the 1990s by a Cuban roller who remained anonymous, and the name is said to come from a smuggler who helped Cubans flee after the revolution — or, according to what the owner told a retailer in 2024, from a story of corojo seeds taken out of the island. This atlas attributes these tales to those who tell them and retains none as a founding date.

What is established begins in the early or mid-2000s: Craig Cunningham, an American entrepreneur, has owned and run the house since then, and he established his own factory in Estelí, Tabacalera Carreras, where everything is grown or bought, blended and rolled. The house has its headquarters in California and its market in the United States; in 2024, at Inter-tabac in Dortmund, it announced worldwide distribution with Kopp Tobaccos. The factory also rolls for other brands, which it does not name.

The catalogue counts thirteen lines — Cashmere, Dictator''s Hand, Hellcat, Chupacabra, Unforsaken, Black Cross, Brown Cross, Bloodline, Mr Brownstone — and the house says most are Nicaraguan puros. Chupacabra, in three versions, is the one that made its reputation.',
        '[{"name":"Chupacabra","color":"#4A3728","force":"Full","wrapper":"Nicaraguan; San Andrés for the 10 Años","vitolas":[],"story":"The line that made the reputation — Natural, Maduro and 10 Años, pigtail cap."},{"name":"Cashmere","color":"#C9A96E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"One of the thirteen lines; the house says most are Nicaraguan puros."}]',
        'Esteban Carreras es un nombre del que nadie sabe muy bien a quién designa, y la prensa del oficio tiene la honestidad de decirlo: la marca habría sido lanzada en los años 1990 por un torcedor cubano que permaneció anónimo, y el nombre vendría de un pasador que ayudó a cubanos a huir tras la revolución — o, según lo que el propietario contó a un minorista en 2024, de una historia de semillas de corojo sacadas de la isla. Este atlas atribuye esos relatos a quienes los cuentan y no retiene ninguno como fecha de fundación.

Lo establecido empieza a principios o mediados de los años 2000: Craig Cunningham, empresario estadounidense, posee y dirige la casa desde entonces, y estableció en Estelí su propia fábrica, la Tabacalera Carreras, donde todo se cultiva o se compra, se liga y se lía. La casa tiene su sede en California y su mercado en Estados Unidos; en 2024, en la Inter-tabac de Dortmund, anunció su distribución mundial con Kopp Tobaccos. La fábrica lía también para otras marcas, que no nombra.

El catálogo cuenta trece líneas — Cashmere, Dictator''s Hand, Hellcat, Chupacabra, Unforsaken, Black Cross, Brown Cross, Bloodline, Mr Brownstone — y la casa dice que la mayoría son puros nicaragüenses. Chupacabra, en tres versiones, es la que hizo su reputación.',
        '[{"name":"Chupacabra","color":"#4A3728","force":"Full","wrapper":"Nicaragüense; San Andrés para la 10 Años","vitolas":[],"story":"La línea que hizo la reputación — Natural, Maduro y 10 Años, perilla de cola de cerdo."},{"name":"Cashmere","color":"#C9A96E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Una de las trece líneas; la casa dice que la mayoría son puros nicaragüenses."}]',
        'Esteban Carreras ist ein Name, von dem niemand recht weiß, wen er bezeichnet, und die Fachpresse ist ehrlich genug, das zu sagen: Die Marke soll in den 1990ern von einem anonym gebliebenen kubanischen Roller gestartet worden sein, und der Name soll von einem Schleuser stammen, der Kubanern nach der Revolution zur Flucht verhalf — oder, nach dem, was der Eigentümer 2024 einem Händler erzählte, von einer Geschichte um Corojo-Saatgut, das von der Insel geschafft wurde. Dieser Atlas schreibt diese Erzählungen denen zu, die sie erzählen, und behält keine als Gründungsdatum.

Was feststeht, beginnt Anfang oder Mitte der 2000er: Craig Cunningham, ein amerikanischer Unternehmer, besitzt und führt das Haus seither und errichtete in Estelí seine eigene Fabrik, die Tabacalera Carreras, wo alles angebaut oder gekauft, geblendet und gerollt wird. Das Haus hat seinen Sitz in Kalifornien und seinen Markt in den Vereinigten Staaten; 2024 kündigte es auf der Inter-tabac in Dortmund den weltweiten Vertrieb mit Kopp Tobaccos an. Die Fabrik rollt auch für andere Marken, die sie nicht nennt.

Der Katalog zählt dreizehn Linien — Cashmere, Dictator''s Hand, Hellcat, Chupacabra, Unforsaken, Black Cross, Brown Cross, Bloodline, Mr Brownstone —, und das Haus sagt, die meisten seien nicaraguanische Puros. Chupacabra, in drei Versionen, ist die, die seinen Ruf begründete.',
        '[{"name":"Chupacabra","color":"#4A3728","force":"Full","wrapper":"Nicaraguanisch; San Andrés für die 10 Años","vitolas":[],"story":"Die Linie, die den Ruf begründete — Natural, Maduro und 10 Años, mit Pigtail."},{"name":"Cashmere","color":"#C9A96E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine der dreizehn Linien; das Haus sagt, die meisten seien nicaraguanische Puros."}]',
        'Esteban Carreras 这个名字，没人真正知道指的是谁，行业媒体也坦然承认：据说品牌在1990年代由一位匿名的古巴卷工创立，名字据说来自一位在革命后帮助古巴人出逃的引路人——或者，按店主2024年对一家零售商所讲，来自一段把 corojo 种子带出岛的故事。本图集把这些说法归于讲述者，不采用任何一个作为创立日期。

可以确定的从2000年代初或中期开始：美国企业家克雷格·坎宁安自那时起拥有并经营这家公司，并在埃斯特利建立了自己的工厂 Tabacalera Carreras，种植或采购、调配和卷制都在那里。公司总部在加利福尼亚，市场在美国；2024年在多特蒙德 Inter-tabac 展会上，它宣布与 Kopp Tobaccos 合作进行全球分销。工厂也为其他品牌代工，但不点名。

目录有十三条线——Cashmere、Dictator''s Hand、Hellcat、Chupacabra、Unforsaken、Black Cross、Brown Cross、Bloodline、Mr Brownstone——公司说大多数是尼加拉瓜纯料。有三个版本的 Chupacabra 是为它赢得名声的那一款。',
        '[{"name":"Chupacabra","color":"#4A3728","force":"Full","wrapper":"尼加拉瓜；10 Años 用圣安德烈斯","vitolas":[],"story":"成就名声的系列——Natural、Maduro 与 10 Años，猪尾茄帽。"},{"name":"Cashmere","color":"#C9A96E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"十三条线之一；公司说大多数是尼加拉瓜纯料。"}]',
        'إستيبان كاريراس اسمٌ لا يعرف أحد حقًّا من يعنيه، وصحافة المهنة من الأمانة بحيث تقول ذلك: يُقال إنّ العلامة أُطلقت في التسعينيات على يد لفّاف كوبي بقي مجهولًا، وإنّ الاسم جاء من مهرّب ساعد كوبيين على الفرار بعد الثورة — أو، بحسب ما روى المالك لتاجر تجزئة سنة 2024، من حكاية بذور كوروخو أُخرجت من الجزيرة. ينسب هذا الأطلس هذه الروايات إلى رواتها ولا يحتفظ بأيّ منها تاريخَ تأسيس.

الثابت يبدأ في مطلع الألفية أو منتصف عقدها الأوّل: كريغ كننغهام، رجل أعمال أمريكي، يملك الدار ويديرها منذ ذلك الحين، وأقام في إستيلي مصنعه الخاص، Tabacalera Carreras، حيث يُزرع كلّ شيء أو يُشترى ويُمزج ويُلفّ. مقرّ الدار في كاليفورنيا وسوقها في الولايات المتحدة؛ وفي 2024، في معرض Inter-tabac في دورتموند، أعلنت توزيعها العالمي مع Kopp Tobaccos. ويلفّ المصنع أيضًا لعلامات أخرى لا يسمّيها.

يضمّ الكتالوج ثلاثة عشر خطًّا — Cashmere وDictator''s Hand وHellcat وChupacabra وUnforsaken وBlack Cross وBrown Cross وBloodline وMr Brownstone — وتقول الدار إنّ معظمها سيجارات نيكاراغوية خالصة. وChupacabra، بنسخه الثلاث، هو ما صنع سمعتها.',
        '[{"name":"Chupacabra","color":"#4A3728","force":"Full","wrapper":"نيكاراغوي؛ سان أندريس للـ10 Años","vitolas":[],"story":"الخطّ الذي صنع السمعة — Natural وMaduro و10 Años، بغطاء ذيل الخنزير."},{"name":"Cashmere","color":"#C9A96E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"أحد الخطوط الثلاثة عشر؛ تقول الدار إنّ معظمها سيجارات نيكاراغوية خالصة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── NACSA ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('NACSA',
        'nicaragua',
        '1995 — Estelí (NATSA, Bermejo et Rothman)',
        'Usine propre — Nicaragua American Cigars S.A., Estelí ; nouveau bâtiment vers 2015',
        'halfwheel.com « Puro Sabor 2017: Day 5 » (la fabrique d''origine, Nicaragua American Tobacco S.A. — NATSA —, lancée en 1995 par Juan Francisco Bermejo avec des associés dont Lew Rothman, ancien propriétaire de JR Cigar ; elle roulait exclusivement pour JR, des cigares bon marché ; nouveau bâtiment deux ans plus tôt ; Raúl Disla engagé pour la production ; clients Asylum et Mi Querida de Saka ; Finca Guadalupe, la ferme de la famille Oliva Tobacco) ; cigaraficionado.com « Larry Palombo Joins Nicaraguan Cigar Factory » (13 janvier 2016 : NACSA, ex-NATSA, détenue en partie par l''Oliva Tobacco Co. de Tampa — fondée par Angel Oliva Sr. dans les années 1930, sans lien avec Oliva Cigars ; Palombo, quarante-quatre ans de métier, ancien vice-président tabac d''Altadis USA, vient réassembler les marques déposées de la fabrique : Red Dot, Villar y Villar, La Rosa Especial, Aristoff) ; cigar-coop.com (Patina roulée à NACSA depuis 2019)',
        'NACSA est une fabrique avant d''être une marque, et l''atlas l''écrit comme telle. Elle est née en 1995 à Estelí sous le nom de Nicaragua American Tobacco S.A. — NATSA —, lancée par Juan Francisco Bermejo avec des associés dont Lew Rothman, le propriétaire de JR Cigar : pendant des années elle a roulé exclusivement pour ce détaillant, des cigares bon marché, dont Quorum, avant que J.C. Newman n''ouvre PENSA en 2011 et ne rapatrie la ligne. L''atlas raconte PENSA à la fiche J.C. Newman.

Le tournant est venu vers 2015 : un nouveau bâtiment, plus bas dans la même rue, et la décision de faire du premium. La fabrique a engagé Raúl Disla pour la production et attiré des clients — Asylum, dont l''atlas porte la fiche, la Mi Querida de Steve Saka, puis Patina en 2019. Elle appartient en partie à l''Oliva Tobacco Company, le courtier en feuilles de Tampa fondé par Angel Oliva Sr. dans les années 1930, qui cultive à la Finca Guadalupe voisine — une maison sans lien avec Oliva Cigars, et la confusion est assez fréquente pour que la presse la signale à chaque fois.

En janvier 2016, Larry Palombo, quarante-quatre ans de métier et ancien vice-président tabac d''Altadis USA, est venu réassembler les marques déposées que la fabrique gardait dans un tiroir — Red Dot, Villar y Villar, La Rosa Especial, Aristoff — pour les mettre sur le marché avec les tabacs d''Oliva. C''est pour ces marques-là que NACSA a une fiche ici, et non seulement une place dans celles des autres.',
        '[{"name":"Red Dot","color":"#B22222","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''une des marques déposées de la fabrique, réassemblée par Larry Palombo en 2016 sur les tabacs d''Oliva."},{"name":"Villar y Villar","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Un nom d''ancienne marque, sorti du tiroir avec La Rosa Especial et Aristoff."}]',
        'NACSA is a factory before it is a brand, and this atlas writes it as such. It was born in 1995 in Estelí as Nicaragua American Tobacco S.A. — NATSA —, launched by Juan Francisco Bermejo with partners including Lew Rothman, the owner of JR Cigar: for years it rolled exclusively for that retailer, inexpensive cigars, Quorum among them, until J.C. Newman opened PENSA in 2011 and brought the line home. This atlas tells PENSA at the J.C. Newman entry.

The turn came around 2015: a new building, further down the same road, and the decision to make premium cigars. The factory hired Raúl Disla for production and attracted clients — Asylum, whose entry this atlas carries, Steve Saka''s Mi Querida, then Patina in 2019. It is partly owned by the Oliva Tobacco Company, the Tampa leaf broker founded by Angel Oliva Sr. in the 1930s, which grows at the neighbouring Finca Guadalupe — a house with no link to Oliva Cigars, and the confusion is common enough that the press points it out every time.

In January 2016, Larry Palombo, forty-four years in the trade and former vice-president of tobacco at Altadis USA, came to reblend the registered brands the factory kept in a drawer — Red Dot, Villar y Villar, La Rosa Especial, Aristoff — to bring them to market with Oliva''s tobaccos. It is for those brands that NACSA has an entry here, and not only a place in other houses'' entries.',
        '[{"name":"Red Dot","color":"#B22222","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"One of the factory''s registered brands, reblended by Larry Palombo in 2016 on Oliva''s tobaccos."},{"name":"Villar y Villar","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"An old brand name, taken out of the drawer with La Rosa Especial and Aristoff."}]',
        'NACSA es una fábrica antes que una marca, y este atlas la escribe como tal. Nació en 1995 en Estelí con el nombre de Nicaragua American Tobacco S.A. — NATSA —, lanzada por Juan Francisco Bermejo con socios entre los que estaba Lew Rothman, el propietario de JR Cigar: durante años lió exclusivamente para ese minorista, puros baratos, Quorum entre ellos, hasta que J.C. Newman abrió PENSA en 2011 y repatrió la línea. Este atlas cuenta PENSA en la ficha J.C. Newman.

El giro llegó hacia 2015: un edificio nuevo, más abajo en la misma calle, y la decisión de hacer premium. La fábrica contrató a Raúl Disla para la producción y atrajo clientes — Asylum, cuya ficha lleva este atlas, la Mi Querida de Steve Saka, luego Patina en 2019. Pertenece en parte a la Oliva Tobacco Company, el corredor de hoja de Tampa fundado por Angel Oliva Sr. en los años 1930, que cultiva en la vecina Finca Guadalupe — una casa sin vínculo con Oliva Cigars, y la confusión es lo bastante frecuente para que la prensa la señale cada vez.

En enero de 2016, Larry Palombo, cuarenta y cuatro años de oficio y ex vicepresidente de tabaco de Altadis USA, vino a religar las marcas registradas que la fábrica guardaba en un cajón — Red Dot, Villar y Villar, La Rosa Especial, Aristoff — para llevarlas al mercado con los tabacos de Oliva. Es por esas marcas que NACSA tiene ficha aquí, y no solo un lugar en las de otros.',
        '[{"name":"Red Dot","color":"#B22222","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Una de las marcas registradas de la fábrica, religada por Larry Palombo en 2016 con los tabacos de Oliva."},{"name":"Villar y Villar","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Un nombre de marca antigua, sacado del cajón con La Rosa Especial y Aristoff."}]',
        'NACSA ist eine Fabrik, bevor sie eine Marke ist, und dieser Atlas schreibt sie so. Sie entstand 1995 in Estelí als Nicaragua American Tobacco S.A. — NATSA —, gegründet von Juan Francisco Bermejo mit Partnern, darunter Lew Rothman, der Eigentümer von JR Cigar: Jahrelang rollte sie ausschließlich für diesen Händler, preiswerte Zigarren, darunter Quorum, bis J.C. Newman 2011 PENSA eröffnete und die Linie heimholte. Diesen Atlas erzählt PENSA im Eintrag J.C. Newman.

Die Wende kam um 2015: ein neues Gebäude, weiter unten an derselben Straße, und die Entscheidung, Premium zu machen. Die Fabrik stellte Raúl Disla für die Produktion ein und zog Kunden an — Asylum, deren Eintrag dieser Atlas führt, Steve Sakas Mi Querida, dann Patina 2019. Sie gehört zum Teil der Oliva Tobacco Company, dem Tampaer Blatthändler, den Angel Oliva Sr. in den 1930ern gründete und der auf der benachbarten Finca Guadalupe anbaut — ein Haus ohne Verbindung zu Oliva Cigars, und die Verwechslung ist häufig genug, dass die Presse jedes Mal darauf hinweist.

Im Januar 2016 kam Larry Palombo, vierundvierzig Jahre im Metier und ehemaliger Vizepräsident Tabak von Altadis USA, um die eingetragenen Marken, die die Fabrik in einer Schublade hielt — Red Dot, Villar y Villar, La Rosa Especial, Aristoff —, neu zu blenden und mit Olivas Tabaken auf den Markt zu bringen. Für diese Marken hat NACSA hier einen Eintrag, und nicht nur einen Platz in denen anderer.',
        '[{"name":"Red Dot","color":"#B22222","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine der eingetragenen Marken der Fabrik, 2016 von Larry Palombo auf Olivas Tabaken neu geblendet."},{"name":"Villar y Villar","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Ein alter Markenname, mit La Rosa Especial und Aristoff aus der Schublade geholt."}]',
        'NACSA 先是一家工厂，然后才是品牌，本图集也如此书写。它1995年在埃斯特利以 Nicaragua American Tobacco S.A.——NATSA——之名诞生，由胡安·弗朗西斯科·贝尔梅霍与包括 JR Cigar 老板卢·罗斯曼在内的合伙人创立：多年来它只为这家零售商卷制廉价雪茄，Quorum 在其中，直到 J.C. Newman 2011年开设 PENSA 并把该线收回。本图集在 J.C. Newman 词条讲了 PENSA。

转折出现在2015年前后：同一条街往下的一座新楼，以及做优质雪茄的决定。工厂聘请劳尔·迪斯拉负责生产，并吸引了客户——本图集载有词条的 Asylum、史蒂夫·萨卡的 Mi Querida，再是2019年的 Patina。它部分属于 Oliva Tobacco Company，坦帕的烟叶经纪商，由老安赫尔·奥利瓦创办于1930年代，在邻近的 Finca Guadalupe 种植——与 Oliva Cigars 毫无关系，这种混淆常见到媒体每次都要指出。

2016年1月，从业四十四年、曾任 Altadis USA 烟草副总裁的拉里·帕隆博前来重新调配工厂压在抽屉里的注册品牌——Red Dot、Villar y Villar、La Rosa Especial、Aristoff——用奥利瓦的烟叶推向市场。正是为了这些品牌，NACSA 在此有自己的词条，而不只是出现在别家的词条里。',
        '[{"name":"Red Dot","color":"#B22222","force":"Medium","wrapper":"未公开","vitolas":[],"story":"工厂的注册品牌之一，2016年由拉里·帕隆博用奥利瓦的烟叶重新调配。"},{"name":"Villar y Villar","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"一个旧品牌名，与 La Rosa Especial 和 Aristoff 一起从抽屉里取出。"}]',
        'ناكسا مصنعٌ قبل أن تكون علامة، وهكذا يكتبها هذا الأطلس. وُلدت سنة 1995 في إستيلي باسم Nicaragua American Tobacco S.A. — NATSA — أطلقها خوان فرانسيسكو برميخو مع شركاء منهم لو روثمان، صاحب JR Cigar: لسنوات لفّت حصرًا لهذا التاجر سيجارات رخيصة، منها Quorum، إلى أن فتحت J.C. Newman مصنع PENSA سنة 2011 واستعادت الخطّ. يروي هذا الأطلس PENSA في بطاقة J.C. Newman.

جاء المنعطف نحو 2015: مبنًى جديد أسفل الشارع نفسه، وقرارُ صنع الفاخر. استقدم المصنع راؤول ديسلا للإنتاج واجتذب زبائن — Asylum التي يحمل هذا الأطلس بطاقتها، وMi Querida لستيف ساكا، ثم Patina سنة 2019. وهو مملوك جزئيًّا لـOliva Tobacco Company، سمسار الأوراق في تامبا الذي أسّسه أنخيل أوليفا الأب في الثلاثينيات ويزرع في Finca Guadalupe المجاورة — دارٌ لا صلة لها بـOliva Cigars، والخلط شائع بما يكفي لتنبّه إليه الصحافة في كلّ مرّة.

وفي كانون الثاني/يناير 2016 جاء لاري بالومبو، أربع وأربعون سنة في المهنة ونائب رئيس سابق للتبغ في Altadis USA، ليعيد مزج العلامات المسجّلة التي كان المصنع يحتفظ بها في درج — Red Dot وVillar y Villar وLa Rosa Especial وAristoff — لطرحها في السوق بأتبغة أوليفا. من أجل هذه العلامات لناكسا بطاقةٌ هنا، لا مجرّد مكان في بطاقات الآخرين.',
        '[{"name":"Red Dot","color":"#B22222","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"إحدى العلامات المسجّلة للمصنع، أعاد مزجها لاري بالومبو سنة 2016 على أتبغة أوليفا."},{"name":"Villar y Villar","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"اسمُ علامة قديمة، أُخرج من الدرج مع La Rosa Especial وAristoff."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Patina Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Patina Cigars',
        'nicaragua',
        '2015 — Chicago ; chez Mombacho, puis NACSA',
        'Sans usine — Mombacho, Granada (2017–2019), puis NACSA, Estelí',
        'cigar-coop.com « Cigar Review: Patina Anniversary » (fondée en 2015 par Mo Maali à Chicago ; premiers assemblages chez Mombacho en 2017 ; rupture en 2019 et production transférée à NACSA, Estelí) ; halfwheel.com « Patina Cigars Adds Oro de Nicaragua as New Core Line » et « Patina Prepares to Ship Red Pill » (Red Pill expédié le 28 octobre 2025) ; cigar-review.com (Patina y Viso Verdigris, 2025, collaboration avec Viso Horny de Tyler Jeffery, faite à NACSA, 3 000 cigares, dix boutiques) ; patinacigars.com',
        'Patina — la patine, celle que prennent le cuivre et les objets qu''on a tenus — est une maison de Chicago fondée en 2015 par Mo Maali, et l''atlas la classe au Nicaragua, où elle est roulée. Elle a commencé chez Mombacho, la fabrique de Granada dont l''atlas raconte la fermeture : les premiers assemblages sont sortis en 2017 de cette demeure coloniale au pied du volcan. En 2019, Maali s''en est séparé et a transféré sa production à NACSA, à Estelí, la fabrique dont l''atlas porte désormais la fiche — le même chemin, en sens inverse, que la maison Mombacho elle-même quelques années plus tard, vers la fermeture.

Depuis, le catalogue s''écrit à Estelí : Oro de Nicaragua, ligne régulière, un Anniversary, et en 2025 deux sorties — Verdigris, un vert-de-gris, en collaboration avec Viso Horny de Tyler Jeffery, trois mille cigares pour dix boutiques, et Red Pill, expédié le 28 octobre. Une maison de petites séries nommées comme des couleurs et des matières, dans la manière de la scène boutique américaine que l''atlas a beaucoup décrite.

La fiche existe parce que la fabrique est nommée, à chaque étape — c''est la règle — et parce que la presse du métier a suivi la maison jusqu''à cette année.',
        '[{"name":"Oro de Nicaragua","color":"#C9A96E","force":"Medium","wrapper":"Puro nicaraguayen","vitolas":[],"story":"La ligne régulière, roulée à NACSA."},{"name":"Red Pill","color":"#B22222","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Expédié le 28 octobre 2025."},{"name":"Verdigris","color":"#3E8B6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Le vert-de-gris — 2025, avec Viso Horny, trois mille cigares pour dix boutiques."}]',
        'Patina — the patina copper takes, and objects long held — is a Chicago house founded in 2015 by Mo Maali, and this atlas classifies it in Nicaragua, where it is rolled. It began at Mombacho, the Granada factory whose closure this atlas tells: the first blends came out in 2017 from that colonial house at the foot of the volcano. In 2019, Maali parted from it and moved production to NACSA, in Estelí, the factory whose entry this atlas now carries — the same road, in reverse, that the Mombacho house itself took a few years later, towards closure.

Since then, the catalogue is written in Estelí: Oro de Nicaragua, a regular line, an Anniversary, and in 2025 two releases — Verdigris, in collaboration with Tyler Jeffery''s Viso Horny, three thousand cigars for ten shops, and Red Pill, shipped on 28 October. A house of small series named like colours and materials, in the manner of the American boutique scene this atlas has described at length.

The entry exists because the factory is named, at every step — that is the rule — and because the trade press has followed the house to this year.',
        '[{"name":"Oro de Nicaragua","color":"#C9A96E","force":"Medium","wrapper":"Nicaraguan puro","vitolas":[],"story":"The regular line, rolled at NACSA."},{"name":"Red Pill","color":"#B22222","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Shipped on 28 October 2025."},{"name":"Verdigris","color":"#3E8B6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Verdigris — 2025, with Viso Horny, three thousand cigars for ten shops."}]',
        'Patina — la pátina, la que toman el cobre y los objetos que se han tenido en la mano — es una casa de Chicago fundada en 2015 por Mo Maali, y este atlas la clasifica en Nicaragua, donde se lía. Empezó en Mombacho, la fábrica de Granada cuyo cierre cuenta este atlas: las primeras ligadas salieron en 2017 de aquella casona colonial al pie del volcán. En 2019, Maali se separó y trasladó su producción a NACSA, en Estelí, la fábrica cuya ficha lleva ahora este atlas — el mismo camino, en sentido inverso, que la propia casa Mombacho unos años después, hacia el cierre.

Desde entonces, el catálogo se escribe en Estelí: Oro de Nicaragua, línea regular, un Anniversary, y en 2025 dos salidas — Verdigris, un cardenillo, en colaboración con Viso Horny de Tyler Jeffery, tres mil puros para diez tiendas, y Red Pill, enviado el 28 de octubre. Una casa de pequeñas series nombradas como colores y materias, a la manera de la escena boutique estadounidense que este atlas ha descrito mucho.

La ficha existe porque la fábrica está nombrada, en cada etapa — es la regla — y porque la prensa del oficio ha seguido a la casa hasta este año.',
        '[{"name":"Oro de Nicaragua","color":"#C9A96E","force":"Medium","wrapper":"Puro nicaragüense","vitolas":[],"story":"La línea regular, liada en NACSA."},{"name":"Red Pill","color":"#B22222","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Enviado el 28 de octubre de 2025."},{"name":"Verdigris","color":"#3E8B6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"El cardenillo — 2025, con Viso Horny, tres mil puros para diez tiendas."}]',
        'Patina — die Patina, die Kupfer und lange gehaltene Gegenstände annehmen — ist ein Haus aus Chicago, 2015 von Mo Maali gegründet, und dieser Atlas ordnet es in Nicaragua ein, wo es gerollt wird. Es begann bei Mombacho, der Fabrik in Granada, deren Schließung dieser Atlas erzählt: Die ersten Blends kamen 2017 aus jenem Kolonialhaus am Fuß des Vulkans. 2019 trennte sich Maali davon und verlegte die Produktion zu NACSA in Estelí, der Fabrik, deren Eintrag dieser Atlas nun führt — derselbe Weg, in umgekehrter Richtung, den das Haus Mombacho selbst einige Jahre später ging, zur Schließung.

Seither wird der Katalog in Estelí geschrieben: Oro de Nicaragua, eine reguläre Linie, ein Anniversary, und 2025 zwei Veröffentlichungen — Verdigris, ein Grünspan, in Zusammenarbeit mit Tyler Jefferys Viso Horny, dreitausend Zigarren für zehn Läden, und Red Pill, am 28. Oktober ausgeliefert. Ein Haus kleiner Serien, benannt wie Farben und Materialien, in der Art der amerikanischen Boutique-Szene, die dieser Atlas ausführlich beschrieben hat.

Der Eintrag existiert, weil die Fabrik bei jedem Schritt benannt ist — das ist die Regel — und weil die Fachpresse das Haus bis in dieses Jahr begleitet hat.',
        '[{"name":"Oro de Nicaragua","color":"#C9A96E","force":"Medium","wrapper":"Nicaraguanischer Puro","vitolas":[],"story":"Die reguläre Linie, bei NACSA gerollt."},{"name":"Red Pill","color":"#B22222","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Am 28. Oktober 2025 ausgeliefert."},{"name":"Verdigris","color":"#3E8B6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Grünspan — 2025, mit Viso Horny, dreitausend Zigarren für zehn Läden."}]',
        'Patina——铜器和久经把玩之物所生的包浆——是2015年由莫·马阿利在芝加哥创立的公司，本图集把它归入卷制之地尼加拉瓜。它从 Mombacho 起步，即本图集讲过其关闭的格拉纳达工厂：最初的配方2017年出自火山脚下那座殖民时期宅邸。2019年马阿利与之分道扬镳，把生产转到埃斯特利的 NACSA——本图集如今载有其词条——与 Mombacho 公司自身几年后走向关闭的路正好相反。

此后目录在埃斯特利书写：常规线 Oro de Nicaragua、一款 Anniversary，以及2025年的两款——Verdigris，铜绿之名，与泰勒·杰弗里的 Viso Horny 合作，三千支供十家店；Red Pill，10月28日发货。一家以颜色和材质命名小批量产品的公司，正是本图集多番描述的美国精品雪茄圈的作派。

词条得以存在，是因为每一步的工厂都被点名——这是规则——也因为行业媒体一直追踪这家公司到今年。',
        '[{"name":"Oro de Nicaragua","color":"#C9A96E","force":"Medium","wrapper":"尼加拉瓜纯料","vitolas":[],"story":"常规线，在 NACSA 卷制。"},{"name":"Red Pill","color":"#B22222","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2025年10月28日发货。"},{"name":"Verdigris","color":"#3E8B6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"铜绿——2025年，与 Viso Horny 合作，三千支供十家店。"}]',
        'باتينا — الصدأ النبيل الذي يكسو النحاس والأشياء التي طال إمساكها — دارٌ من شيكاغو أسّسها مو معالي سنة 2015، ويصنّفها هذا الأطلس في نيكاراغوا حيث تُلفّ. بدأت لدى Mombacho، مصنع غرناطة الذي يروي هذا الأطلس إغلاقه: خرجت المزجات الأولى سنة 2017 من ذلك البيت الاستعماري عند سفح البركان. وفي 2019 انفصل عنه معالي ونقل إنتاجه إلى NACSA في إستيلي، المصنع الذي يحمل هذا الأطلس بطاقته الآن — الطريق نفسه، بالاتجاه المعاكس، الذي سلكته دار Mombacho نفسها بعد سنوات قليلة نحو الإغلاق.

ومنذئذٍ يُكتب الكتالوج في إستيلي: Oro de Nicaragua، خطّ منتظم، وAnniversary، وفي 2025 إصداران — Verdigris، الزنجار، بالتعاون مع Viso Horny لتايلر جيفري، ثلاثة آلاف سيجار لعشرة متاجر، وRed Pill الذي شُحن في 28 تشرين الأوّل/أكتوبر. دارُ سلاسل صغيرة تُسمّى كالألوان والموادّ، على طريقة مشهد البوتيك الأمريكي الذي وصفه هذا الأطلس كثيرًا.

البطاقة موجودة لأنّ المصنع مسمًّى في كلّ مرحلة — هذه هي القاعدة — ولأنّ صحافة المهنة تابعت الدار حتى هذه السنة.',
        '[{"name":"Oro de Nicaragua","color":"#C9A96E","force":"Medium","wrapper":"نيكاراغوي خالص","vitolas":[],"story":"الخطّ المنتظم، يُلفّ في NACSA."},{"name":"Red Pill","color":"#B22222","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"شُحن في 28 تشرين الأوّل/أكتوبر 2025."},{"name":"Verdigris","color":"#3E8B6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الزنجار — 2025، مع Viso Horny، ثلاثة آلاف سيجار لعشرة متاجر."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Powstanie ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Powstanie',
        'nicaragua',
        '2015 — Deltona (Floride) ; chez Nica Sueño',
        'Sans usine — Fábrica de Tabacos Nica Sueño S.A. (RoMa Craft), Estelí',
        'halfwheel.com « Powstanie Coming From Cigar Hustler & NicaSueño » (28 mars 2015 : les frères Mike et Greg Szczepankewicz, propriétaires de la boutique Cigar Hustler à Deltona, Floride, lancent leur marque, roulée à la Fábrica de Tabacos Nica Sueño — première marque hors RoMa Craft vendue par la fabrique à plusieurs détaillants ; nom polonais, « insurrection », logo inspiré des symboles de la résistance polonaise ; deux assemblages composés chacun par un frère avec Esteban Disla et Skip Martin, choisis en aveugle par les clients — Habano en mai, Maduro en août ; boîtes de 21) ; halfwheel.com « Powstanie San Andrés Corona Gorda » et « Powstanie Connecticut Perfecto » ; cigar-coop.com « PCA 2023: Powstanie Cigars » (Pospiech Cigars distribue aussi Fable et Chogüí)',
        'Powstanie — po-cha-nié, « insurrection » en polonais — est la marque de deux frères détaillants de Floride, Mike et Greg Szczepankewicz, propriétaires de la boutique Cigar Hustler à Deltona. Elle est née en 2015 d''une manière que la presse a trouvée digne d''être racontée : chaque frère a composé son propre assemblage avec Esteban Disla et Skip Martin, à la Fábrica de Tabacos Nica Sueño d''Estelí — la fabrique de RoMa Craft, dont l''atlas porte la fiche —, puis les clients de la boutique ont goûté les deux en aveugle. Le Habano de Mike est sorti en mai, le Maduro de Greg en août ; c''était la première marque étrangère à RoMa Craft que la fabrique acceptait de vendre à plusieurs détaillants.

Le logo emprunte aux symboles de la résistance polonaise de la Seconde Guerre mondiale, et le nom dit l''origine de la famille. Le catalogue a grandi depuis autour de capes : Habano, Maduro broadleaf, Connecticut, San Andrés — en perfectos et corona gordas, boîtes de vingt et un, comme la fabrique les aime.

La société des frères, Pospiech, est devenue aussi un distributeur : c''est elle qui porte Fable et Chogüí, deux fiches de cet atlas. Une marque de détaillant, donc — mais avec une fabrique nommée, un catalogue permanent et dix ans de presse, ce qui est exactement la ligne que l''atlas a tirée entre Sindicato et Black Swan.',
        '[{"name":"Powstanie Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"L''assemblage de Mike, choisi en aveugle par les clients — sorti en mai 2015."},{"name":"Powstanie Maduro","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf maduro","vitolas":[],"story":"L''assemblage de Greg — août 2015."},{"name":"Powstanie San Andrés","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"La cape mexicaine, en corona gorda notamment."}]',
        'Powstanie — po-shan-yah, "uprising" in Polish — is the brand of two retailer brothers from Florida, Mike and Greg Szczepankewicz, owners of the Cigar Hustler shop in Deltona. It was born in 2015 in a way the press found worth telling: each brother composed his own blend with Esteban Disla and Skip Martin, at Fábrica de Tabacos Nica Sueño in Estelí — RoMa Craft''s factory, whose entry this atlas carries —, then the shop''s customers tasted both blind. Mike''s Habano came out in May, Greg''s Maduro in August; it was the first non-RoMa Craft brand the factory agreed to sell to several retailers.

The logo borrows from the symbols of the Polish resistance of the Second World War, and the name states the family''s origin. The catalogue has since grown around wrappers: Habano, broadleaf Maduro, Connecticut, San Andrés — in perfectos and corona gordas, boxes of twenty-one, as the factory likes them.

The brothers'' company, Pospiech, has also become a distributor: it carries Fable and Chogüí, two entries of this atlas. A retailer''s brand, then — but with a named factory, a permanent catalogue and ten years of press, which is exactly the line this atlas drew between Sindicato and Black Swan.',
        '[{"name":"Powstanie Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Mike''s blend, chosen blind by customers — released May 2015."},{"name":"Powstanie Maduro","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf maduro","vitolas":[],"story":"Greg''s blend — August 2015."},{"name":"Powstanie San Andrés","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"The Mexican wrapper, in corona gorda among others."}]',
        'Powstanie — po-cha-ñé, «insurrección» en polaco — es la marca de dos hermanos minoristas de Florida, Mike y Greg Szczepankewicz, propietarios de la tienda Cigar Hustler en Deltona. Nació en 2015 de una manera que la prensa encontró digna de contarse: cada hermano compuso su propia ligada con Esteban Disla y Skip Martin, en la Fábrica de Tabacos Nica Sueño de Estelí — la fábrica de RoMa Craft, cuya ficha lleva este atlas —, y luego los clientes de la tienda probaron ambas a ciegas. El Habano de Mike salió en mayo, el Maduro de Greg en agosto; era la primera marca ajena a RoMa Craft que la fábrica aceptaba vender a varios minoristas.

El logotipo toma prestados los símbolos de la resistencia polaca de la Segunda Guerra Mundial, y el nombre dice el origen de la familia. El catálogo ha crecido desde entonces en torno a capas: Habano, Maduro broadleaf, Connecticut, San Andrés — en perfectos y coronas gordas, cajas de veintiuno, como le gustan a la fábrica.

La sociedad de los hermanos, Pospiech, se ha convertido también en distribuidor: es la que lleva Fable y Chogüí, dos fichas de este atlas. Una marca de minorista, pues — pero con fábrica nombrada, catálogo permanente y diez años de prensa, que es exactamente la línea que este atlas trazó entre Sindicato y Black Swan.',
        '[{"name":"Powstanie Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"La ligada de Mike, elegida a ciegas por los clientes — salida en mayo de 2015."},{"name":"Powstanie Maduro","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf maduro","vitolas":[],"story":"La ligada de Greg — agosto de 2015."},{"name":"Powstanie San Andrés","color":"#4A3728","force":"Full","wrapper":"San Andrés (México)","vitolas":[],"story":"La capa mexicana, en corona gorda entre otros."}]',
        'Powstanie — po-schan-je, „Aufstand" auf Polnisch — ist die Marke zweier Händlerbrüder aus Florida, Mike und Greg Szczepankewicz, Eigentümer des Ladens Cigar Hustler in Deltona. Sie entstand 2015 auf eine Weise, die die Presse erzählenswert fand: Jeder Bruder komponierte seinen eigenen Blend mit Esteban Disla und Skip Martin in der Fábrica de Tabacos Nica Sueño in Estelí — der Fabrik von RoMa Craft, deren Eintrag dieser Atlas führt —, dann probierten die Kunden des Ladens beide blind. Mikes Habano kam im Mai, Gregs Maduro im August; es war die erste RoMa-Craft-fremde Marke, die die Fabrik an mehrere Händler zu verkaufen bereit war.

Das Logo entlehnt Symbole des polnischen Widerstands im Zweiten Weltkrieg, und der Name nennt die Herkunft der Familie. Der Katalog ist seither um Deckblätter gewachsen: Habano, Broadleaf Maduro, Connecticut, San Andrés — in Perfectos und Corona Gordas, Kisten zu einundzwanzig, wie die Fabrik sie mag.

Die Gesellschaft der Brüder, Pospiech, ist auch Distributor geworden: Sie führt Fable und Chogüí, zwei Einträge dieses Atlas. Eine Händlermarke also — aber mit benannter Fabrik, festem Katalog und zehn Jahren Presse, was genau die Linie ist, die dieser Atlas zwischen Sindicato und Black Swan gezogen hat.',
        '[{"name":"Powstanie Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Mikes Blend, blind von den Kunden gewählt — erschienen im Mai 2015."},{"name":"Powstanie Maduro","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf Maduro","vitolas":[],"story":"Gregs Blend — August 2015."},{"name":"Powstanie San Andrés","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Das mexikanische Deckblatt, unter anderem als Corona Gorda."}]',
        'Powstanie——读作「波-沙-涅」，波兰语「起义」——是佛罗里达两位零售商兄弟的品牌：迈克与格雷格·什切潘凯维奇，德尔托纳 Cigar Hustler 店的老板。它2015年的诞生方式媒体觉得值得一讲：兄弟俩各自与埃斯特万·迪斯拉和斯基普·马丁在埃斯特利的 Fábrica de Tabacos Nica Sueño——RoMa Craft 的工厂，本图集载有其词条——调配自己的配方，然后由店里的顾客盲品两款。迈克的 Habano 五月推出，格雷格的 Maduro 八月推出；这是该厂同意向多家零售商出售的头一个非 RoMa Craft 品牌。

标志借用二战波兰抵抗运动的符号，名字道出家族的来源。此后目录围绕茄衣扩展：Habano、broadleaf Maduro、Connecticut、San Andrés——perfecto 和 corona gorda 尺寸，二十一支装，工厂偏爱的装法。

兄弟俩的公司 Pospiech 也成了分销商：正是它经销 Fable 与 Chogüí，本图集的两个词条。所以这是零售商的品牌——但有点名的工厂、常设的目录和十年的媒体记录，正是本图集在 Sindicato 与 Black Swan 之间划下的那条线。',
        '[{"name":"Powstanie Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"迈克的配方，由顾客盲品选出——2015年5月推出。"},{"name":"Powstanie Maduro","color":"#3A2A1E","force":"Full","wrapper":"Broadleaf 马杜罗","vitolas":[],"story":"格雷格的配方——2015年8月。"},{"name":"Powstanie San Andrés","color":"#4A3728","force":"Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"墨西哥茄衣，尤其是 corona gorda 尺寸。"}]',
        'بوفستانيه — تُلفظ بو-شا-نيِه، «انتفاضة» بالبولندية — علامةُ أخوين تاجرَي تجزئة من فلوريدا، مايك وغريغ شتشيبانكيفيتش، صاحبَي متجر Cigar Hustler في دلتونا. وُلدت سنة 2015 بطريقة رأت الصحافة أنّها تستحقّ الرواية: ركّب كلّ أخ مزجته الخاصة مع إستيبان ديسلا وسكيب مارتن في Fábrica de Tabacos Nica Sueño في إستيلي — مصنع RoMa Craft الذي يحمل هذا الأطلس بطاقته — ثم تذوّق زبائن المتجر الاثنتين معصوبي الأعين. خرج Habano مايك في أيّار/مايو، وMaduro غريغ في آب/أغسطس؛ وكانت أوّل علامة من خارج RoMa Craft يقبل المصنع بيعها لعدّة تجّار.

يستعير الشعار رموز المقاومة البولندية في الحرب العالمية الثانية، ويقول الاسم أصل العائلة. ونما الكتالوج منذئذٍ حول الأغلفة: Habano وMaduro برودليف وConnecticut وSan Andrés — بقياسات perfecto وcorona gorda، في علب من واحد وعشرين، كما يحبّها المصنع.

وصارت شركة الأخوين، Pospiech، موزّعًا أيضًا: هي التي تحمل Fable وChogüí، بطاقتين من هذا الأطلس. علامةُ تاجر تجزئة إذن — لكن بمصنع مسمًّى وكتالوج دائم وعشر سنوات من الصحافة، وهو بالضبط الخطّ الذي رسمه هذا الأطلس بين Sindicato وBlack Swan.',
        '[{"name":"Powstanie Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"مزجة مايك، اختارها الزبائن معصوبي الأعين — صدرت في أيّار/مايو 2015."},{"name":"Powstanie Maduro","color":"#3A2A1E","force":"Full","wrapper":"برودليف مادورو","vitolas":[],"story":"مزجة غريغ — آب/أغسطس 2015."},{"name":"Powstanie San Andrés","color":"#4A3728","force":"Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"الغلاف المكسيكي، بقياس corona gorda خصوصًا."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Paul Stulac Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Paul Stulac Cigars',
        'nicaragua',
        '2011 — Canada ; chez Las Villas Cigars, Estelí',
        'Sans usine — Las Villas Cigars, Estelí (Guillermo Peña, maître assembleur)',
        'paulstulaccigars.com (roulés à Las Villas Cigars, Estelí, sous la conduite du maître assembleur Guillermo Peña ; lignes Black Phantom, Red Screaming Sun, Miami Style) ; oakglentobacconist.com et planetcigars.com (lancée à l''IPCPR 2011 ; maison canadienne) ; halfwheel.com « El Nuevo Comienzo Paul Stulac Exclusiva »',
        'Paul Stulac est une maison canadienne, et l''atlas la classe au Nicaragua parce que ses cigares sont roulés à Estelí, chez Las Villas Cigars, sous la conduite de Guillermo Peña, son maître assembleur — une fabrique que l''atlas nomme ici et n''a pas encore décrite. La marque a été lancée à l''IPCPR de 2011, disent les détaillants qui la portent ; la maison elle-même ne date rien sur son site, et l''atlas prend l''année des détaillants faute de mieux, en le disant.

Le style est reconnaissable de loin : des bagues noires, des noms qui viennent du rock et de la nuit — Black Phantom, Red Screaming Sun, Miami Style — et des cigares plutôt corsés. Une esthétique plus qu''un terroir, ce qui n''est pas un reproche : c''est la moitié de la scène boutique nord-américaine.

La fiche s''en tient à ce qu''elle peut nommer : la fabrique, l''assembleur, l''année d''entrée sur le marché. Le reste — les tabacs, les volumes — n''est pas publié.',
        '[{"name":"Black Phantom","color":"#1F1F1F","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Le fantôme noir — la ligne signature."},{"name":"Red Screaming Sun","color":"#B22222","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le soleil rouge hurlant."},{"name":"Miami Style","color":"#3E4A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Un hommage à la manière de Miami — roulé à Estelí."}]',
        'Paul Stulac is a Canadian house, and this atlas classifies it in Nicaragua because its cigars are rolled in Estelí, at Las Villas Cigars, under the direction of Guillermo Peña, its master blender — a factory this atlas names here and has not yet described. The brand was launched at the 2011 IPCPR, say the retailers who carry it; the house itself dates nothing on its site, and this atlas takes the retailers'' year for want of better, saying so.

The style is recognisable from afar: black bands, names that come from rock and the night — Black Phantom, Red Screaming Sun, Miami Style — and rather full-bodied cigars. An aesthetic more than a terroir, which is no reproach: that is half the North American boutique scene.

The entry keeps to what it can name: the factory, the blender, the year of entry on the market. The rest — tobaccos, volumes — is not published.',
        '[{"name":"Black Phantom","color":"#1F1F1F","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The black phantom — the signature line."},{"name":"Red Screaming Sun","color":"#B22222","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The red screaming sun."},{"name":"Miami Style","color":"#3E4A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"A tribute to the Miami manner — rolled in Estelí."}]',
        'Paul Stulac es una casa canadiense, y este atlas la clasifica en Nicaragua porque sus puros se lían en Estelí, en Las Villas Cigars, bajo la dirección de Guillermo Peña, su maestro ligador — una fábrica que este atlas nombra aquí y aún no ha descrito. La marca se lanzó en la IPCPR de 2011, dicen los minoristas que la llevan; la propia casa no fecha nada en su sitio, y este atlas toma el año de los minoristas a falta de algo mejor, diciéndolo.

El estilo se reconoce de lejos: anillas negras, nombres que vienen del rock y de la noche — Black Phantom, Red Screaming Sun, Miami Style — y puros más bien fuertes. Una estética más que un terruño, lo que no es un reproche: es la mitad de la escena boutique norteamericana.

La ficha se atiene a lo que puede nombrar: la fábrica, el ligador, el año de entrada en el mercado. El resto — los tabacos, los volúmenes — no está publicado.',
        '[{"name":"Black Phantom","color":"#1F1F1F","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El fantasma negro — la línea insignia."},{"name":"Red Screaming Sun","color":"#B22222","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El sol rojo que grita."},{"name":"Miami Style","color":"#3E4A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Un homenaje a la manera de Miami — liado en Estelí."}]',
        'Paul Stulac ist ein kanadisches Haus, und dieser Atlas ordnet es in Nicaragua ein, weil seine Zigarren in Estelí gerollt werden, bei Las Villas Cigars, unter der Leitung von Guillermo Peña, seinem Master Blender — einer Fabrik, die dieser Atlas hier nennt und noch nicht beschrieben hat. Die Marke wurde auf der IPCPR 2011 lanciert, sagen die Händler, die sie führen; das Haus selbst datiert auf seiner Seite nichts, und dieser Atlas übernimmt mangels Besserem das Jahr der Händler und sagt es.

Der Stil ist von Weitem erkennbar: schwarze Bauchbinden, Namen aus Rock und Nacht — Black Phantom, Red Screaming Sun, Miami Style — und eher kräftige Zigarren. Eine Ästhetik mehr als ein Terroir, was kein Vorwurf ist: Das ist die halbe nordamerikanische Boutique-Szene.

Der Eintrag hält sich an das, was er benennen kann: die Fabrik, den Blender, das Jahr des Markteintritts. Der Rest — Tabake, Mengen — ist nicht veröffentlicht.',
        '[{"name":"Black Phantom","color":"#1F1F1F","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Das schwarze Phantom — die Signature-Linie."},{"name":"Red Screaming Sun","color":"#B22222","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die rote schreiende Sonne."},{"name":"Miami Style","color":"#3E4A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine Hommage an die Art von Miami — gerollt in Estelí."}]',
        'Paul Stulac 是一家加拿大公司，本图集把它归入尼加拉瓜，因为它的雪茄在埃斯特利的 Las Villas Cigars 卷制，由其调配大师吉列尔莫·佩尼亚主持——本图集在此点名而尚未描述的一家工厂。经销它的零售商说品牌2011年在 IPCPR 展会推出；公司自己的网站不注明任何日期，本图集只好采用零售商的年份，并如实说明。

风格远远就能认出：黑色茄标，名字来自摇滚与黑夜——Black Phantom、Red Screaming Sun、Miami Style——雪茄偏浓烈。与其说是风土，不如说是一种美学，这不是指责：北美精品雪茄圈有一半如此。

词条止于它能点名的东西：工厂、调配师、入市年份。其余——烟叶、产量——未曾公布。',
        '[{"name":"Black Phantom","color":"#1F1F1F","force":"Full","wrapper":"未公开","vitolas":[],"story":"黑色幽灵——招牌系列。"},{"name":"Red Screaming Sun","color":"#B22222","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"嘶吼的红日。"},{"name":"Miami Style","color":"#3E4A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"向迈阿密风格致敬——在埃斯特利卷制。"}]',
        'بول ستولاك دارٌ كندية، ويصنّفها هذا الأطلس في نيكاراغوا لأنّ سيجاراتها تُلفّ في إستيلي لدى Las Villas Cigars، بإشراف غييرمو بينيا، مزّاجها الرئيسي — مصنعٌ يسمّيه هذا الأطلس هنا ولم يصفه بعد. أُطلقت العلامة في معرض IPCPR سنة 2011، كما يقول تجّار التجزئة الذين يحملونها؛ أمّا الدار نفسها فلا تؤرّخ شيئًا على موقعها، ويأخذ هذا الأطلس سنة التجّار في غياب مصدر آخر، قائلًا ذلك.

الطراز يُعرف من بعيد: أحزمة سوداء، وأسماء من الروك والليل — Black Phantom وRed Screaming Sun وMiami Style — وسيجارات قويّة نسبيًّا. جماليّةٌ لا أرض، وليس ذلك عيبًا: فهذا نصف مشهد البوتيك في أمريكا الشمالية.

تقف البطاقة عند ما تستطيع تسميته: المصنع، والمزّاج، وسنة دخول السوق. أمّا الباقي — الأتبغة والكمّيات — فغير منشور.',
        '[{"name":"Black Phantom","color":"#1F1F1F","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"الشبح الأسود — الخطّ المميّز."},{"name":"Red Screaming Sun","color":"#B22222","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الشمس الحمراء الصارخة."},{"name":"Miami Style","color":"#3E4A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"تحيّة لطريقة ميامي — يُلفّ في إستيلي."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Brun del Ré ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Brun del Ré',
        'costarica',
        '2006 — Carlo Corazza ; fabrique en 2007',
        'Usine propre — Escazú, San José ; une quinzaine d''employés, 25 à 30 000 cigares par mois (2019)',
        'cigarjournal.com « Brun del Ré: Costa Rican Cigar Pride » (31 janvier 2019 : Carlo Corazza, Suisse installé de longue date au Costa Rica et propriétaire d''une société horlogère, arrête la cigarette en 1999, découvre le cigare à Cuba en 2001, ouvre un lounge ; en 2006, avec son associé Sam Capuano, décide de fabriquer ; trouve une fabrique à San José en 2007 ; nom de sa grand-mère et d''un blason suisse ; lignes Gold, Premium, Colonial, 1787 Libertad — son premier cigare 100 % costaricien, d''un planteur du sud du pays —, 1638 ; vingt-deux pays, surtout en Europe ; une quinzaine d''employés, 25 à 30 000 cigares par mois) ; brundelrecigars.com ; zigarrenversand.ch et casadelpuro.com (fabrique familiale à Escazú)',
        'Brun del Ré est la maison d''un horloger suisse devenu cigarier au Costa Rica. Carlo Corazza, installé dans le pays de longue date, a arrêté la cigarette en 1999, découvert le cigare à Cuba en 2001 avec un ami, ouvert un lounge, et en 2006 décidé avec son associé Sam Capuano de fabriquer lui-même — il raconte l''avoir annoncé à son associé comme un défi de dessin animé. En 2007 il a trouvé une fabrique à San José ; elle est aujourd''hui à Escazú, dans la famille, avec une quinzaine d''employés et vingt-cinq à trente mille cigares par mois. Le nom est celui de sa grand-mère, et d''un blason suisse vieux de deux siècles.

C''est, avec Puriscal, l''autre foyer du cigare costaricien, et la presse du métier la donne pour la maison la plus connue du pays. Ses lignes s''appellent Gold, Premium, Colonial, 1638, et surtout 1787 Libertad — le premier cigare que Corazza ait fait entièrement en tabac costaricien, d''un planteur du sud du pays ; la date renvoie au temps où le Costa Rica, dans le royaume de Guatemala, fournissait un tabac recherché. La maison vend dans vingt-deux pays, surtout en Europe, et dit ne pas vouloir grandir en quantité.

L''atlas classe ici une maison qui roule et, pour une ligne, cultive — une exception dans un pays d''ateliers, comme Vegas de Santiago à Puriscal.',
        '[{"name":"1787 Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Costaricienne, dit la maison","vitolas":[],"story":"Le premier cigare de la maison entièrement en tabac costaricien, d''un planteur du sud. La date : le Costa Rica dans le royaume de Guatemala."},{"name":"Premium","color":"#6B4226","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"La ligne de fond, avec Gold et Colonial."},{"name":"1638","color":"#4A3728","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Une autre date en guise de nom."}]',
        'Brun del Ré is the house of a Swiss watchmaker turned cigar maker in Costa Rica. Carlo Corazza, long settled in the country, quit cigarettes in 1999, discovered cigars in Cuba in 2001 with a friend, opened a lounge, and in 2006 decided with his partner Sam Capuano to make his own — he tells of announcing it to his partner like a cartoon dare. In 2007 he found a factory in San José; it is now in Escazú, in the family, with some fifteen employees and twenty-five to thirty thousand cigars a month. The name is his grandmother''s, and that of a two-century-old Swiss coat of arms.

It is, with Puriscal, the other home of the Costa Rican cigar, and the trade press gives it as the country''s best-known house. Its lines are called Gold, Premium, Colonial, 1638, and above all 1787 Libertad — the first cigar Corazza made entirely of Costa Rican tobacco, from a grower in the south of the country; the date refers to the time when Costa Rica, within the Kingdom of Guatemala, supplied a sought-after tobacco. The house sells in twenty-two countries, mostly in Europe, and says it does not want to grow in quantity.

This atlas classifies here a house that rolls and, for one line, grows — an exception in a country of workshops, like Vegas de Santiago in Puriscal.',
        '[{"name":"1787 Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Costa Rican, the house says","vitolas":[],"story":"The house''s first cigar entirely of Costa Rican tobacco, from a grower in the south. The date: Costa Rica within the Kingdom of Guatemala."},{"name":"Premium","color":"#6B4226","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"The core line, with Gold and Colonial."},{"name":"1638","color":"#4A3728","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Another date for a name."}]',
        'Brun del Ré es la casa de un relojero suizo convertido en tabaquero en Costa Rica. Carlo Corazza, instalado en el país desde hace mucho, dejó el cigarrillo en 1999, descubrió el puro en Cuba en 2001 con un amigo, abrió un lounge, y en 2006 decidió con su socio Sam Capuano fabricar él mismo — cuenta haberlo anunciado a su socio como un desafío de dibujo animado. En 2007 encontró una fábrica en San José; hoy está en Escazú, en la familia, con una quincena de empleados y de veinticinco a treinta mil puros al mes. El nombre es el de su abuela, y el de un blasón suizo de dos siglos.

Es, con Puriscal, el otro foco del puro costarricense, y la prensa del oficio la da como la casa más conocida del país. Sus líneas se llaman Gold, Premium, Colonial, 1638 y sobre todo 1787 Libertad — el primer puro que Corazza hizo enteramente con tabaco costarricense, de un cultivador del sur del país; la fecha remite al tiempo en que Costa Rica, en el reino de Guatemala, suministraba un tabaco codiciado. La casa vende en veintidós países, sobre todo en Europa, y dice no querer crecer en cantidad.

Este atlas clasifica aquí una casa que lía y, para una línea, cultiva — una excepción en un país de talleres, como Vegas de Santiago en Puriscal.',
        '[{"name":"1787 Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Costarricense, dice la casa","vitolas":[],"story":"El primer puro de la casa enteramente con tabaco costarricense, de un cultivador del sur. La fecha: Costa Rica en el reino de Guatemala."},{"name":"Premium","color":"#6B4226","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La línea de fondo, con Gold y Colonial."},{"name":"1638","color":"#4A3728","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Otra fecha como nombre."}]',
        'Brun del Ré ist das Haus eines Schweizer Uhrmachers, der in Costa Rica Zigarrenmacher wurde. Carlo Corazza, seit Langem im Land ansässig, hörte 1999 mit Zigaretten auf, entdeckte 2001 mit einem Freund in Kuba die Zigarre, eröffnete eine Lounge und beschloss 2006 mit seinem Partner Sam Capuano, selbst zu produzieren — er erzählt, es seinem Partner wie eine Zeichentrick-Mutprobe angekündigt zu haben. 2007 fand er eine Fabrik in San José; heute steht sie in Escazú, in Familienhand, mit rund fünfzehn Angestellten und fünfundzwanzig- bis dreißigtausend Zigarren im Monat. Der Name ist der seiner Großmutter und eines zwei Jahrhunderte alten Schweizer Wappens.

Sie ist, mit Puriscal, der andere Herd der costa-ricanischen Zigarre, und die Fachpresse nennt sie das bekannteste Haus des Landes. Ihre Linien heißen Gold, Premium, Colonial, 1638 und vor allem 1787 Libertad — die erste Zigarre, die Corazza ganz aus costa-ricanischem Tabak machte, von einem Pflanzer im Süden des Landes; das Datum verweist auf die Zeit, als Costa Rica im Königreich Guatemala einen begehrten Tabak lieferte. Das Haus verkauft in zweiundzwanzig Ländern, vor allem in Europa, und sagt, es wolle nicht in der Menge wachsen.

Dieser Atlas ordnet hier ein Haus ein, das rollt und, für eine Linie, anbaut — eine Ausnahme in einem Land der Werkstätten, wie Vegas de Santiago in Puriscal.',
        '[{"name":"1787 Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Costa-ricanisch, sagt das Haus","vitolas":[],"story":"Die erste Zigarre des Hauses ganz aus costa-ricanischem Tabak, von einem Pflanzer im Süden. Das Datum: Costa Rica im Königreich Guatemala."},{"name":"Premium","color":"#6B4226","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Die Grundlinie, mit Gold und Colonial."},{"name":"1638","color":"#4A3728","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Ein weiteres Datum als Name."}]',
        'Brun del Ré 是一位在哥斯达黎加转做雪茄的瑞士钟表商的公司。长期定居该国的卡洛·科拉扎1999年戒了烟，2001年与朋友在古巴发现雪茄，开了一家雪茄吧，2006年与合伙人萨姆·卡普阿诺决定自己制作——他说当时像动画片里那样向合伙人下了战书。2007年他在圣何塞找到一家工厂；如今工厂在埃斯卡苏，由家族经营，约十五名员工，月产两万五千到三万支。名字取自他的祖母，以及一个两百年历史的瑞士家徽。

它与普里斯卡尔一道，是哥斯达黎加雪茄的另一个中心，行业媒体称之为该国知名度高的公司。各系列名为 Gold、Premium、Colonial、1638，尤其是 1787 Libertad——科拉扎第一支完全用哥斯达黎加烟叶制作的雪茄，烟叶来自该国南部的一位种植者；年份指向哥斯达黎加尚属危地马拉王国、供应抢手烟草的年代。公司销往二十二个国家，主要在欧洲，并表示不想在数量上扩张。

本图集在此收录一家既卷制、又为一条线种植的公司——在一个作坊之国里的例外，一如普里斯卡尔的 Vegas de Santiago。',
        '[{"name":"1787 Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"公司称为哥斯达黎加烟叶","vitolas":[],"story":"公司第一支完全用哥斯达黎加烟叶制作的雪茄，烟叶来自南部一位种植者。年份：危地马拉王国时期的哥斯达黎加。"},{"name":"Premium","color":"#6B4226","force":"Medium","wrapper":"未公开","vitolas":[],"story":"基础系列，与 Gold 和 Colonial 并列。"},{"name":"1638","color":"#4A3728","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"又一个以年份为名的系列。"}]',
        'برون ديل ريه دارُ صانع ساعات سويسري صار صانع سيجار في كوستاريكا. كارلو كورازا، المقيم في البلد منذ زمن طويل، ترك السجائر سنة 1999، واكتشف السيجار في كوبا سنة 2001 مع صديق، وافتتح صالونًا، وفي 2006 قرّر مع شريكه سام كابوانو أن يصنع بنفسه — ويروي أنّه أعلن ذلك لشريكه كتحدٍّ من الرسوم المتحرّكة. وفي 2007 وجد مصنعًا في سان خوسيه؛ وهو اليوم في إسكاسو، في العائلة، بنحو خمسة عشر موظّفًا وخمسة وعشرين إلى ثلاثين ألف سيجار في الشهر. الاسم اسم جدّته، واسم شعارِ نبالة سويسري عمره قرنان.

إنّها، مع بوريسكال، الموقد الآخر للسيجار الكوستاريكي، وتقدّمها صحافة المهنة دارَ البلد المعروفة. تُسمّى خطوطها Gold وPremium وColonial و1638، وقبل كلّ شيء 1787 Libertad — أوّل سيجار صنعه كورازا كلّه من تبغ كوستاريكي، من مزارع في جنوب البلاد؛ والتاريخ يحيل إلى الزمن الذي كانت فيه كوستاريكا، في مملكة غواتيمالا، تورّد تبغًا مطلوبًا. تبيع الدار في اثنين وعشرين بلدًا، في أوروبا خصوصًا، وتقول إنّها لا تريد النموّ في الكمّية.

يصنّف هذا الأطلس هنا دارًا تلفّ، وتزرع لخطّ واحد — استثناءٌ في بلد الورش، مثل Vegas de Santiago في بوريسكال.',
        '[{"name":"1787 Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"كوستاريكي، كما تقول الدار","vitolas":[],"story":"أوّل سيجار للدار كلّه من تبغ كوستاريكي، من مزارع في الجنوب. التاريخ: كوستاريكا في مملكة غواتيمالا."},{"name":"Premium","color":"#6B4226","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الخطّ الأساس، مع Gold وColonial."},{"name":"1638","color":"#4A3728","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"تاريخٌ آخر اسمًا."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── El Septimo ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('El Septimo',
        'costarica',
        '2005 — Genève ; Younan Company depuis mars 2019',
        'Usine propre revendiquée — El Septimo Cigar Factory, Costa Rica',
        'premiumcigars.org « The Precision of Premium: How El Septimo is Changing the Game » (fondée au début des années 2000 et connue en Europe et au Moyen-Orient depuis 2005 ; rachetée par Zaya Younan en mars 2019 ; fabrique au Costa Rica ; collection Alexandra lancée en juin 2019, pensée pour les femmes ; Sacred Arts Collection présentée à la PCA 2021, sept cigares au nom d''artistes et des sept jours de la création ; la maison dit appliquer à ses champs les méthodes de ses vignobles de Bordeaux et de Saint-Émilion) ; halfwheel.com « El Septimo Releasing Two New Cigars, New Accessory Line at TPE 2021 » ; cigaraficionado.com « El Septimo Launches Cigar Line for Women » ; elseptimo.com (fondée à Genève en 2005 ; cape, sous-cape et tripe entièrement costariciennes, cultivées et roulées au Costa Rica)',
        'El Septimo est une marque de luxe née à Genève — fondée, dit-elle, en 2005, connue d''abord en Europe et au Moyen-Orient — et l''atlas la classe au Costa Rica, où ses cigares sont roulés dans une fabrique qu''elle dit sienne. En mars 2019, Zaya Younan, financier d''origine irakienne à la tête de la Younan Company, un groupe de luxe qui possède des châteaux et des vignobles à Bordeaux et Saint-Émilion, l''a rachetée ; sa fille Alexandra en dirige le marketing, et la collection qui porte son prénom, lancée en juin 2019, est pensée pour les femmes.

La maison affirme beaucoup, et l''atlas rapporte : que cape, sous-cape et tripe sont entièrement costariciennes, cultivées et roulées au Costa Rica ; qu''elle applique à ses champs les méthodes de ses vignobles ; que son tabac pousse à plus de deux mille huit cents mètres — ce dernier chiffre, la fiche le laisse à la maison, aucune source extérieure ne l''ayant vérifié. Ce qui se voit sans discussion : des prix très élevés, des étuis lourds, et un catalogue qui va vite — la Sacred Arts Collection de 2021, sept cigares au nom d''artistes et des sept jours de la création, cent trente boutiques américaines la même année avec l''ambition d''en atteindre mille.

Une maison qui vend du luxe avant de vendre du tabac, ce que l''atlas dit sans juger, parce qu''il y en a d''autres ici — Atabey, à quelques kilomètres, en est une.',
        '[{"name":"Sacred Arts Collection","color":"#8B1A6B","force":"Medium-Full","wrapper":"Costaricienne, dit la maison","vitolas":[],"story":"PCA 2021 — sept cigares au nom d''artistes et des sept jours de la création."},{"name":"Alexandra Collection","color":"#C9A96E","force":"Medium","wrapper":"Costaricienne, dit la maison","vitolas":[],"story":"Juin 2019 — deux lignes pensées pour les femmes, tabacs vieillis dix ans, dit la maison."}]',
        'El Septimo is a luxury brand born in Geneva — founded, it says, in 2005, known first in Europe and the Middle East — and this atlas classifies it in Costa Rica, where its cigars are rolled in a factory it says is its own. In March 2019, Zaya Younan, a financier of Iraqi origin at the head of the Younan Company, a luxury group that owns châteaux and vineyards in Bordeaux and Saint-Émilion, bought it; his daughter Alexandra runs its marketing, and the collection that bears her name, launched in June 2019, is designed for women.

The house claims a great deal, and this atlas reports: that wrapper, binder and filler are entirely Costa Rican, grown and rolled in Costa Rica; that it applies its vineyards'' methods to its fields; that its tobacco grows above two thousand eight hundred metres — that last figure the entry leaves to the house, no outside source having verified it. What can be seen without discussion: very high prices, heavy cases, and a fast-moving catalogue — the 2021 Sacred Arts Collection, seven cigars named after artists and the seven days of creation, a hundred and thirty American shops the same year with the ambition of reaching a thousand.

A house that sells luxury before it sells tobacco, which this atlas says without judging, because there are others here — Atabey, a few kilometres away, is one.',
        '[{"name":"Sacred Arts Collection","color":"#8B1A6B","force":"Medium-Full","wrapper":"Costa Rican, the house says","vitolas":[],"story":"PCA 2021 — seven cigars named after artists and the seven days of creation."},{"name":"Alexandra Collection","color":"#C9A96E","force":"Medium","wrapper":"Costa Rican, the house says","vitolas":[],"story":"June 2019 — two lines designed for women, tobaccos aged ten years, the house says."}]',
        'El Septimo es una marca de lujo nacida en Ginebra — fundada, dice, en 2005, conocida primero en Europa y Oriente Medio — y este atlas la clasifica en Costa Rica, donde sus puros se lían en una fábrica que dice suya. En marzo de 2019, Zaya Younan, financiero de origen iraquí al frente de la Younan Company, un grupo de lujo que posee castillos y viñedos en Burdeos y Saint-Émilion, la compró; su hija Alexandra dirige el marketing, y la colección que lleva su nombre, lanzada en junio de 2019, está pensada para las mujeres.

La casa afirma mucho, y este atlas lo reporta: que capa, capote y tripa son enteramente costarricenses, cultivados y liados en Costa Rica; que aplica a sus campos los métodos de sus viñedos; que su tabaco crece a más de dos mil ochocientos metros — esta última cifra la ficha la deja a la casa, sin que ninguna fuente externa la haya verificado. Lo que se ve sin discusión: precios muy altos, estuches pesados y un catálogo que va rápido — la Sacred Arts Collection de 2021, siete puros con nombres de artistas y de los siete días de la creación, ciento treinta tiendas estadounidenses el mismo año con la ambición de llegar a mil.

Una casa que vende lujo antes de vender tabaco, lo que este atlas dice sin juzgar, porque hay otras aquí — Atabey, a pocos kilómetros, es una.',
        '[{"name":"Sacred Arts Collection","color":"#8B1A6B","force":"Medium-Full","wrapper":"Costarricense, dice la casa","vitolas":[],"story":"PCA 2021 — siete puros con nombres de artistas y de los siete días de la creación."},{"name":"Alexandra Collection","color":"#C9A96E","force":"Medium","wrapper":"Costarricense, dice la casa","vitolas":[],"story":"Junio de 2019 — dos líneas pensadas para las mujeres, tabacos añejados diez años, dice la casa."}]',
        'El Septimo ist eine Luxusmarke, geboren in Genf — gegründet, wie sie sagt, 2005, zuerst in Europa und im Nahen Osten bekannt —, und dieser Atlas ordnet sie in Costa Rica ein, wo ihre Zigarren in einer Fabrik gerollt werden, die sie als ihre eigene bezeichnet. Im März 2019 kaufte sie Zaya Younan, ein Finanzier irakischer Herkunft an der Spitze der Younan Company, eines Luxuskonzerns mit Schlössern und Weingütern in Bordeaux und Saint-Émilion; seine Tochter Alexandra leitet das Marketing, und die Kollektion, die ihren Vornamen trägt, im Juni 2019 lanciert, ist für Frauen gedacht.

Das Haus behauptet viel, und dieser Atlas berichtet: dass Deckblatt, Umblatt und Einlage vollständig costa-ricanisch seien, angebaut und gerollt in Costa Rica; dass es die Methoden seiner Weingüter auf seine Felder anwende; dass sein Tabak über zweitausendachthundert Metern wachse — diese letzte Zahl überlässt der Eintrag dem Haus, da keine externe Quelle sie bestätigt hat. Was sich ohne Diskussion sehen lässt: sehr hohe Preise, schwere Etuis und ein schnell wachsender Katalog — die Sacred Arts Collection von 2021, sieben Zigarren mit Namen von Künstlern und den sieben Schöpfungstagen, hundertdreißig amerikanische Läden im selben Jahr mit dem Ziel von tausend.

Ein Haus, das Luxus verkauft, bevor es Tabak verkauft, was dieser Atlas ohne Urteil sagt, weil es hier andere gibt — Atabey, wenige Kilometer entfernt, ist eines.',
        '[{"name":"Sacred Arts Collection","color":"#8B1A6B","force":"Medium-Full","wrapper":"Costa-ricanisch, sagt das Haus","vitolas":[],"story":"PCA 2021 — sieben Zigarren mit Namen von Künstlern und den sieben Schöpfungstagen."},{"name":"Alexandra Collection","color":"#C9A96E","force":"Medium","wrapper":"Costa-ricanisch, sagt das Haus","vitolas":[],"story":"Juni 2019 — zwei für Frauen gedachte Linien, zehn Jahre gereifte Tabake, sagt das Haus."}]',
        'El Septimo 是一个诞生于日内瓦的奢侈品牌——据它自己说创立于2005年，先在欧洲和中东出名——本图集把它归入哥斯达黎加，它的雪茄在那里一家它自称属于自己的工厂卷制。2019年3月，伊拉克裔金融家、Younan Company 掌门人扎亚·尤南收购了它；该奢侈品集团在波尔多和圣埃美隆拥有城堡和葡萄园。他的女儿亚历山德拉负责市场，以她名字命名的系列于2019年6月推出，为女性而设计。

公司的说法很多，本图集照录：茄衣、茄套和填充全部为哥斯达黎加烟叶，在哥斯达黎加种植和卷制；它把自家葡萄园的方法用于烟田；它的烟草生长在海拔两千八百米以上——最后这个数字词条留给公司自己，没有任何外部来源核实过。无需争论就能看到的：极高的价格、沉重的雪茄盒，以及快速扩张的目录——2021年的 Sacred Arts Collection，七支以艺术家和创世七日命名的雪茄；同年进入一百三十家美国店铺，志在一千家。

一家先卖奢华、后卖烟草的公司，本图集如实说出而不评判，因为这里还有别的——几公里外的 Atabey 便是其一。',
        '[{"name":"Sacred Arts Collection","color":"#8B1A6B","force":"Medium-Full","wrapper":"公司称为哥斯达黎加烟叶","vitolas":[],"story":"2021年 PCA——七支以艺术家与创世七日命名的雪茄。"},{"name":"Alexandra Collection","color":"#C9A96E","force":"Medium","wrapper":"公司称为哥斯达黎加烟叶","vitolas":[],"story":"2019年6月——两条为女性设计的线，公司称烟叶陈化十年。"}]',
        'إل سيبتيمو علامةُ رفاهية وُلدت في جنيف — أُسّست، كما تقول، سنة 2005، وعُرفت أوّلًا في أوروبا والشرق الأوسط — ويصنّفها هذا الأطلس في كوستاريكا حيث تُلفّ سيجاراتها في مصنع تقول إنّه لها. في آذار/مارس 2019 اشتراها زايا يونان، المموّل ذو الأصل العراقي على رأس Younan Company، مجموعة رفاهية تملك قصورًا وكروم عنب في بوردو وسانت إميليون؛ وتدير ابنته ألكسندرا التسويق، والمجموعة التي تحمل اسمها، المطلقة في حزيران/يونيو 2019، مصمَّمة للنساء.

تدّعي الدار الكثير، وينقل هذا الأطلس: أنّ الغلاف والورقة الرابطة والحشوة كوستاريكية بالكامل، مزروعة ومُلفوفة في كوستاريكا؛ وأنّها تطبّق على حقولها أساليب كرومها؛ وأنّ تبغها ينمو فوق ألفين وثمانمئة متر — هذا الرقم الأخير تتركه البطاقة للدار، إذ لم يتحقّق منه أيّ مصدر خارجي. أمّا ما يُرى بلا نقاش: أسعارٌ مرتفعة جدًّا، وعلب ثقيلة، وكتالوج يتقدّم بسرعة — مجموعة Sacred Arts لسنة 2021، سبعة سيجارات بأسماء فنّانين وأيّام الخلق السبعة، ومئة وثلاثون متجرًا أمريكيًّا في السنة نفسها بطموح بلوغ الألف.

دارٌ تبيع الرفاهية قبل أن تبيع التبغ، وهو ما يقوله هذا الأطلس من دون حكم، لأنّ هنا أخريات — Atabey، على بُعد كيلومترات قليلة، إحداها.',
        '[{"name":"Sacred Arts Collection","color":"#8B1A6B","force":"Medium-Full","wrapper":"كوستاريكي، كما تقول الدار","vitolas":[],"story":"PCA 2021 — سبعة سيجارات بأسماء فنّانين وأيّام الخلق السبعة."},{"name":"Alexandra Collection","color":"#C9A96E","force":"Medium","wrapper":"كوستاريكي، كما تقول الدار","vitolas":[],"story":"حزيران/يونيو 2019 — خطّان مصمَّمان للنساء، أتبغة معتّقة عشر سنين، كما تقول الدار."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);


-- ── NICARAGUA : `brands` reecrit en litteral complet (65 entrees) ──
