onic":false},{"name":"Nicoya","desc":"Maison australienne roulée à Estelí — l''Australie ne cultive plus depuis 2006","iconic":false},{"name":"Dunbarton Tobacco & Trust","desc":"Steve Saka, ex-Drew Estate, parti monter sa maison sans usine","iconic":true},{"name":"RoMa Craft Tobac","desc":"Commencée dans un garage, puis son propre atelier à Estelí","iconic":true},{"name":"Viaje","desc":"Plus de gamme régulière depuis 2012 : rien que des séries limitées","iconic":false},{"name":"Room101","desc":"D''un bijoutier au cigare ; trois manufactures, deux pays","iconic":false},{"name":"L''Atelier","desc":"La seconde maison de Pete Johnson, chez My Father comme Tatuaje","iconic":false},{"name":"La Aroma de Cuba","desc":"Nom cubain des années 1880, refait par Pepin García en 2009","iconic":false},{"name":"Southern Draw","desc":"Robert et Sharon Holt — un seul atelier, ce qui est rare","iconic":false},{"name":"HVC Cigars","desc":"Havana City ; dix ans sans usine, puis la sienne en 2021","iconic":true},{"name":"Fratello","desc":"Un ingénieur de la NASA passé au cigare","iconic":false},{"name":"Curivari","desc":"Grecque de tête, cubaine d''intention, nicaraguayenne de matière","iconic":false},{"name":"Black Label Trading Co.","desc":"Une fabrique conçue comme un atelier d''artiste","iconic":false},{"name":"Asylum","desc":"L''autre moitié de CLE — et une fabrique qui fut un cinéma","iconic":false},{"name":"Micallef","desc":"Une panne de voiture, un Texan, et trois générations cubaines","iconic":false},{"name":"Gurkha","desc":"Sans usine jusqu''en 2017, puis propriétaire de la sienne à Estelí","iconic":false},{"name":"Protocol","desc":"Deux policiers, aucune usine — La Zona puis San Lotano","iconic":false},{"name":"Regius","desc":"Maison londonienne de 2010, roulée chez Plasencia","iconic":false},{"name":"Cornelius & Anthony","desc":"Cent cinquante ans de tabac en Virginie, roulés à Estelí","iconic":false},{"name":"262 Cigars","desc":"Le nom est une date : février 1962, la signature de l''embargo","iconic":false},{"name":"Emilio Cigars","desc":"Trois fabriques, trois familles, un seul nom sur la bague","iconic":false},{"name":"Nomad","desc":"Le nom était un programme : elle a changé d''atelier et de pays","iconic":false},{"name":"7-20-4","desc":"Une adresse de Manchester fermée en 1962, reprise en 2006","iconic":false},{"name":"Cuban Crafters","desc":"Une boutique à Miami, mais la fabrique est à Estelí","iconic":false},{"name":"J. Fuego","desc":"Estelí, 2016 — le Corojo de Pinar del Río, et l''atelier où 7-20-4 est roulée","iconic":false},{"name":"Luciano Cigars","desc":"Estelí — la fabrique d''un Cubain parti en 2005, au prénom d''un financier brésilien ; roule Crowned Heads et Ozgener","iconic":false},{"name":"Agrotabacos","desc":"Condega, 1995 — les Ortez ; 60 % de la production pour des tiers, dont Altadis","iconic":false},{"name":"Karen Berger Cigars","desc":"Estelí — la fabrique de Kiki Berger, reprise par sa veuve en 2014 ; c''est aussi celle de Cuban Crafters","iconic":false},{"name":"Rojas Cigars","desc":"Estelí — un ancien cinéma ; l''assembleur d''Ezra Zion, Nomad et Stolen Throne","iconic":false},{"name":"Miami Cigar & Co.","desc":"1989 — Nestor et Mariana Miranda ; sans usine, la Collection chez My Father, Don Lino chez La Aurora","iconic":false},{"name":"1502 Cigars","desc":"L''année où Colomb touche le Nicaragua ; roulée chez Plasencia","iconic":false},{"name":"Crux Cigars","desc":"Deux détaillants du Minnesota passés de l''autre côté du comptoir en 2014 ; chez Plasencia","iconic":false},{"name":"Blanco Cigars","desc":"1998 — les cousins des Plasencia, de Pinar del Río ; roulée à Estelí","iconic":false},{"name":"Stolen Throne","desc":"Virginie, 2019 — roulée par Noel Rojas","iconic":false},{"name":"Ezra Zion","desc":"Texas, 2012 — roulée par Noel Rojas ; propriétaire de Nomad depuis 2018","iconic":false},{"name":"Ozgener Family Cigars","desc":"2022 — le fils du fondateur de CAO ; chez Luciano et La Alianza","iconic":false},{"name":"All Saints Cigars","desc":"2018 — chez Rocky Patel, à la TAVICUSA","iconic":false},{"name":"Serino Cigar Co.","desc":"2016 — père et fils ; chez La Corona","iconic":false},{"name":"Sindicato Cigar Group","desc":"2013 — des détaillants devenus propriétaires de marque ; chez Aganorsa","iconic":false},{"name":"Fable Cigars","desc":"2016 — revenue en 2025 chez Córdoba & Morales","iconic":false},{"name":"Esteban Carreras","desc":"Craig Cunningham, années 2000 — usine propre, Tabacalera Carreras","iconic":false},{"name":"NACSA","desc":"1995 — la fabrique d''Estelí qui roule Asylum, Mi Querida et Patina, et ses marques propres","iconic":false},{"name":"Patina Cigars","desc":"Chicago, 2015 — chez Mombacho puis NACSA","iconic":false},{"name":"Powstanie","desc":"Deltona, 2015 — la marque des frères Szczepankewicz chez RoMa Craft","iconic":false},{"name":"Paul Stulac Cigars","desc":"Canada, 2011 — chez Las Villas Cigars","iconic":false}]' WHERE `id` = 'nicaragua';

