UPDATE `producer_countries` SET `brands` = '[{"desc":"Du dessinateur du Behike à sa propre maison","name":"Atabey","iconic":true},{"desc":"Le versant classique de Selected Tobacco","name":"Byron","iconic":false},{"desc":"Des tabacs mûris cinq ans avant roulage","name":"Bandolero","iconic":false},{"desc":"Maison britannique sans champs, roulée au Costa Rica","name":"Casdagli","iconic":false},{"name":"Selected Tobacco","desc":"Nelson Alfonso — la maison derrière Atabey, Byron et Bandolero","iconic":false},{"name":"Vegas de Santiago","desc":"La seule du pays qui cultive ce qu''elle roule","iconic":true},{"name":"Bombay Tobak","desc":"2014 — MBombay, troisième marque sortie de Puriscal","iconic":false},{"name":"Brun del Ré","desc":"Carlo Corazza, 2006 — usine propre à Escazú ; 1787 Libertad en tabac costaricien","iconic":true},{"name":"El Septimo","desc":"Genève 2005, Younan depuis 2019 — le luxe roulé au Costa Rica","iconic":false}]' WHERE `id` = 'costarica';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Esteban Carreras','NACSA','Patina Cigars','Powstanie','Paul Stulac Cigars','Brun del Ré','El Septimo')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

