  (NULL,'migration 216','systeme','trois_reportees_regle_ortega','marque',0,
   'La Sirena (derniere presse juin 2022), Reinado (octobre 2022), Amendola (fevrier 2023, boutique signalee fermee) : activite non etablie. Une fiche au present sur une maison peut-etre dormante serait la faute de Mombacho a l envers'),
  (NULL,'migration 216','systeme','origines_attribuees','marque',0,
   'Esteban Carreras : la presse dit elle-meme ses origines mysterieuses, la fiche ne retient aucune date de fondation. Paul Stulac : 2011 vient des detaillants. El Septimo : 2 800 metres et 100 % costaricien restent a la maison');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Esteban Carreras','NACSA','Patina Cigars','Powstanie','Paul Stulac Cigars','Brun del Ré','El Septimo')) = 7 AS sept_fiches,
  (SELECT `brands` LIKE '%NACSA%' AND `brands` LIKE '%Powstanie%' FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT `brands` LIKE '%Brun del R%' AND `brands` LIKE '%El Septimo%' FROM `producer_countries` WHERE `id` = 'costarica') AS costarica_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 216') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
